:root{--bg:#10130f;--panel:#181d17;--cream:#f6f0e5;--gold:#d7ad64;--gold2:#f1d59a;--muted:#a8ad9f;--line:rgba(241,213,154,.18);--green:#304a36}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--bg);color:var(--cream);font-family:'DM Sans',sans-serif;line-height:1.65;overflow-x:hidden}body:before{content:"";position:fixed;inset:0;pointer-events:none;opacity:.13;background-image:radial-gradient(rgba(255,255,255,.18) .6px,transparent .6px);background-size:5px 5px;z-index:-1}a{color:inherit;text-decoration:none}button{font:inherit}.nav{position:fixed;z-index:50;inset:0 0 auto;display:flex;align-items:center;justify-content:space-between;padding:20px clamp(20px,5vw,80px);background:rgba(16,19,15,.78);backdrop-filter:blur(16px);border-bottom:1px solid transparent;transition:.3s}.nav.scrolled{border-color:var(--line);padding-top:13px;padding-bottom:13px}.brand{font:700 1.25rem 'Playfair Display',serif;letter-spacing:.16em;color:var(--gold2)}.brand small{display:block;font:500 .58rem 'DM Sans',sans-serif;letter-spacing:.35em;color:var(--muted);margin-top:2px}.navlinks{display:flex;align-items:center;gap:28px;font-size:.75rem;letter-spacing:.14em;text-transform:uppercase}.navlinks a{transition:color .25s}.navlinks a:hover{color:var(--gold2)}.pill{display:inline-flex;align-items:center;justify-content:center;padding:12px 19px;border:1px solid var(--gold);color:var(--gold2);letter-spacing:.1em;text-transform:uppercase;font-size:.72rem;transition:.25s;cursor:pointer;background:transparent}.pill:hover,.pill.fill{background:var(--gold);color:#15150f}.hero{min-height:94vh;display:grid;grid-template-columns:1.05fr .95fr;align-items:center;gap:40px;padding:140px clamp(20px,7vw,110px) 80px;position:relative;isolation:isolate;background:radial-gradient(ellipse at 80% 40%,rgba(99,62,30,.35),transparent 38%),radial-gradient(ellipse at 5% 90%,rgba(44,78,50,.42),transparent 45%)}.eyebrow{color:var(--gold);letter-spacing:.28em;text-transform:uppercase;font-size:.7rem;font-weight:700;display:flex;align-items:center;gap:12px}.eyebrow:before{content:"";width:35px;height:1px;background:var(--gold)}h1,h2,h3{font-family:'Playfair Display',serif}h1{font-size:clamp(3rem,7.5vw,7.5rem);line-height:.98;letter-spacing:-.045em;margin:24px 0}h1 em{font-weight:500;color:var(--gold2)}.lead{max-width:520px;color:var(--muted);font-size:1.04rem}.actions{display:flex;gap:13px;flex-wrap:wrap;margin-top:30px}.hero-art{position:relative;min-height:420px;display:grid;place-items:center}.hero-circle{width:min(36vw,440px);aspect-ratio:1;border-radius:50%;border:1px solid rgba(241,213,154,.45);display:grid;place-items:center;box-shadow:0 0 0 18px rgba(241,213,154,.025),0 0 100px rgba(215,173,100,.12);animation:float 6s ease-in-out infinite}.hero-circle img{width:88%;height:88%;object-fit:cover;border-radius:50%;filter:saturate(.85);mask-image:radial-gradient(circle,#000 58%,transparent 72%)}.orbit{position:absolute;width:min(41vw,500px);aspect-ratio:1;border:1px dashed rgba(241,213,154,.25);border-radius:50%;animation:spin 42s linear infinite}.orbit:after{content:"✦";position:absolute;top:12%;right:12%;color:var(--gold2);font-size:1.6rem}.hero-note{position:absolute;bottom:4%;left:0;background:rgba(24,29,23,.9);border:1px solid var(--line);padding:15px 20px;backdrop-filter:blur(8px)}.hero-note strong{display:block;font:600 1.3rem 'Playfair Display';color:var(--gold2)}.hero-note span{font-size:.7rem;letter-spacing:.14em;color:var(--muted);text-transform:uppercase}.ticker{overflow:hidden;border-block:1px solid var(--line);background:#151914;padding:15px 0}.ticker div{display:flex;width:max-content;gap:45px;white-space:nowrap;color:var(--gold2);font:italic 1.35rem 'Playfair Display';animation:marquee 35s linear infinite}.section{padding:100px clamp(20px,7vw,110px)}.section-head{display:flex;justify-content:space-between;align-items:end;gap:24px;margin-bottom:35px}.section-head h2{font-size:clamp(2rem,4vw,3.5rem);line-height: