dow:0 0 0 14px rgba(215,173,100,.04),0 0 0 28px rgba(215,173,100,.025)}.story h2{font-size:clamp(2rem,4vw,3.5rem);line-height:1.15;margin:15px 0}.story p{color:var(--muted)}.footer{border-top:1px solid var(--line);padding:35px clamp(20px,7vw,110px);display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;color:var(--muted);font-size:.8rem}.admin-link{color:var(--gold2)}.reveal{opacity:0;transform:translateY(22px);transition:opacity .7s,transform .7s}.reveal.visible{opacity:1;transform:none}@keyframes float{50%{transform:translateY(-12px)}}@keyframes spin{to{transform:rotate(360deg)}}@keyframes marquee{to{transform:translateX(-50%)}}@media(max-width:900px){.hero{grid-template-columns:1fr;text-align:center;padding-top:130px}.hero .eyebrow,.actions{justify-content:center}.lead{margin-inline:auto}.hero-art{min-height:340px}.hero-circle{width:min(65vw,360px)}.orbit{width:min(73vw,420px)}.hero-note{left:5%}.menu-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.story{grid-template-columns:1fr;gap:35px}.story-visual{min-height:290px}}@media(max-width:600px){.nav{padding:15px 18px}.brand{font-size:1rem}.navlinks{gap:10px}.navlinks a:not(.nav-cta){display:none}.nav-cta{padding:9px 11px;font-size:.62rem}.hero{padding-inline:22px;min-height:auto;padding-bottom:65px}.hero h1{font-size:clamp(3rem,15vw,5rem)}.hero-art{min-height:280px}.hero-note{bottom:0;padding:10px 14px}.section{padding:70px 20px}.section-head{align-items:start;flex-direction:column}.menu-grid{grid-template-columns:1fr}.dish-img{height:245px}.footer{padding:28px 20px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;scroll-behavior:auto!important;transition-duration:.01ms!important}}
</style>
